'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var incrnansumprod = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof incrnansumprod, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an accumulator function', function test( t ) {
	t.equal( typeof incrnansumprod(), 'function', 'returns a function' );
	t.end();
});

tape( 'the initial accumulated value is `null`', function test( t ) {
	var acc = incrnansumprod();
	t.equal( acc(), null, 'returns expected value' );
	t.end();
});

tape( 'the accumulator function incrementally computes a sum of products (aka dot product), ignoring NaN values', function test( t ) {
	var expected;
	var actual;
	var data;
	var acc;
	var sum;
	var N;
	var x;
	var y;
	var i;
	var a;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, NaN ],
		[ 2.0, 5.0 ],
		[ NaN, -4.0 ],
		[ 3.0, 0.0 ],
		[ NaN, NaN ]
	];
	N = data.length;

	expected = [];
	actual = [];
	for ( a = 0; a < N; a++ ) {
		expected.push(undefined);
		actual.push(undefined);
	}

	acc = incrnansumprod();

	sum = 0;
	for ( i = 0; i < N; i++ ) {
		x = data[ i ][ 0 ];
		y = data[ i ][ 1 ];
		if ( isnan( x ) === false && isnan( y ) === false ) {
			sum += x * y;
		}
		expected[ i ] = sum;
		actual[ i ] = acc( x, y );
	}
	t.deepEqual( actual, expected, 'returns expected values' );
	t.end();
});

tape( 'if not provided an input value, the accumulator function returns the current sum of products', function test( t ) {
	var data;
	var acc;
	var i;

	data = [
		[ 2.0, 3.0 ],
		[ 3.0, NaN ],
		[ 2.0, 5.0 ],
		[ NaN, -4.0 ],
		[ 3.0, 0.0 ],
		[ NaN, NaN ]
	];
	acc = incrnansumprod();
	for ( i = 0; i < data.length; i++ ) {
		acc( data[ i ][ 0 ], data[ i ][ 1 ] );
	}
	t.equal( acc(), 16.0, 'returns expected value' );
	t.end();
});
